//! Dependency names one keystroke from a popular package: `lodahs`,
//! `reqeusts`, `@babe1/core`. A squat registers the name people mistype and
//! ships something extra; a lockfile that holds one is a repo that typed it.
//! The popular names are bundled (`assets/defaults/popular.txt`,
//! `ecosystem<TAB>name`, regenerated by `scripts/popular.py` from each
//! registry's download ranking) so the check works offline and never asks a
//! registry. A listed name is never a squat, and a name the registry treats
//! as the same as a listed one (separators dropped or swapped: npm refuses
//! them, crates.io and PyPI equate them) is the listed, older package.

use std::collections::{HashMap, HashSet};
use std::sync::LazyLock;

use crate::checks::lockfiles::Package;

/// A dependency that looks like a typo of a popular one.
#[derive(Clone, Debug, PartialEq)]
pub struct Squat {
    pub ecosystem: String,
    pub name: String,
    /// The popular name it is one keystroke from.
    pub near: String,
    /// The popular name is in the same lockfile too: a typo that pulled in a
    /// stranger's package beside the one meant.
    pub both: bool,
}

/// Names shorter than this are words of their own, whatever they are near.
const MIN_LEN: usize = 4;
/// A scope shorter than this is not compared to the popular scopes.
const MIN_SCOPE_LEN: usize = 5;

/// One popular name, ready to compare.
struct Candidate {
    /// As listed, for the finding.
    name: &'static str,
    /// Its canonical form, a char at a time.
    canon: Vec<char>,
}

/// The popular names of one ecosystem, indexed for the check.
#[derive(Default)]
struct Popular {
    /// Every listed name, lowercase, scoped ones included.
    names: HashSet<&'static str>,
    /// The `@scope` of every listed scoped name.
    scopes: HashSet<&'static str>,
    /// Canonical and folded forms: a dependency matching one is the listed
    /// package itself, or a name its registry would have refused.
    canon: HashSet<String>,
    folded: HashSet<String>,
    /// Unscoped names by canonical length: an edit changes the length by at
    /// most one, so only the neighbouring buckets are compared.
    by_len: HashMap<usize, Vec<Candidate>>,
}

/// The bundled list, parsed once, keyed by lowercase ecosystem.
static POPULAR: LazyLock<HashMap<String, Popular>> = LazyLock::new(|| index(crate::defaults::POPULAR));

fn index(list: &'static str) -> HashMap<String, Popular> {
    let mut out: HashMap<String, Popular> = HashMap::new();
    for line in list.lines().map(str::trim) {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let Some((eco, name)) = line.split_once('\t') else { continue };
        let name = name.trim();
        let pop = out.entry(eco.to_ascii_lowercase()).or_default();
        pop.names.insert(name);
        if name.starts_with('@') {
            if let Some((scope, _)) = name.split_once('/') {
                pop.scopes.insert(scope);
            }
            continue;
        }
        let canon = canon(name);
        pop.folded.insert(fold(name));
        pop.by_len.entry(canon.chars().count()).or_default().push(Candidate { name, canon: canon.chars().collect() });
        pop.canon.insert(canon);
    }
    out
}

/// Lowercase with every run of separators as one `-`: how PyPI (PEP 503)
/// and crates.io (`-` and `_`) read a name, and what npm's moniker rules
/// compare before refusing a new name that matches an old one.
fn canon(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for c in name.to_ascii_lowercase().chars() {
        if matches!(c, '-' | '_' | '.') {
            if !out.ends_with('-') {
                out.push('-');
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Lowercase without separators: `node-fetch` and `nodefetch` are one word,
/// and npm refuses the second once the first exists.
fn fold(name: &str) -> String {
    name.to_ascii_lowercase().chars().filter(|c| !matches!(c, '-' | '_' | '.')).collect()
}

/// Optimal string alignment distance, capped at 2: substitutions,
/// insertions, deletions and adjacent transpositions.
pub fn distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.len().abs_diff(b.len()) > 2 {
        return 3;
    }
    let mut prev2: Vec<usize> = Vec::new();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for i in 1..=a.len() {
        let mut cur = vec![i; b.len() + 1];
        for j in 1..=b.len() {
            let cost = usize::from(a[i - 1] != b[j - 1]);
            let mut d = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
            if i > 1 && j > 1 && a[i - 1] == b[j - 2] && a[i - 2] == b[j - 1] {
                d = d.min(prev2[j - 2] + 1);
            }
            cur[j] = d;
        }
        prev2 = prev;
        prev = cur;
    }
    prev[b.len()].min(3)
}

/// How one name differs from another by a single keystroke, if it does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Edit {
    /// Two adjacent letters swapped: `lodahs`.
    Transposition,
    /// A letter typed twice or a double letter typed once: `lodaash`, `expres`.
    Duplication,
    /// A letter swapped for one that looks like it: `@babe1`, `0penai`.
    Confusable,
    /// One letter missing or extra: `lodas`, `lodashs`.
    Omission,
    /// One letter replaced: `lodesh`.
    Substitution,
}

fn confusable_pair(a: char, b: char) -> bool {
    [('1', 'l'), ('1', 'i'), ('0', 'o'), ('5', 's'), ('i', 'l'), ('u', 'v'), ('m', 'n'), ('3', 'e')]
        .iter()
        .any(|(x, y)| (a, b) == (*x, *y) || (a, b) == (*y, *x))
}

/// The single edit that turns `typed` into `meant`, when there is one.
pub fn edit(typed: &str, meant: &str) -> Option<Edit> {
    let a: Vec<char> = typed.chars().collect();
    let b: Vec<char> = meant.chars().collect();
    edit_chars(&a, &b)
}

/// `edit` on names already split into chars. A letter replaced by a
/// separator (`xml-js`, `xml2js`) is a different word, not a slip: the
/// registries own the separator space, so no edit involving one counts.
/// A digit replaced by a digit (`uuidv4`, `uuidv7`) is a version.
fn edit_chars(a: &[char], b: &[char]) -> Option<Edit> {
    if a == b {
        return None;
    }
    if a.len() == b.len() {
        let diffs: Vec<usize> = (0..a.len()).filter(|&i| a[i] != b[i]).collect();
        return match diffs.as_slice() {
            [i] if a[*i] == '-' || b[*i] == '-' => None,
            [i] if a[*i].is_ascii_digit() && b[*i].is_ascii_digit() => None,
            [i] => Some(if confusable_pair(a[*i], b[*i]) { Edit::Confusable } else { Edit::Substitution }),
            [i, j] if *j == i + 1 && a[*i] == b[*j] && a[*j] == b[*i] => Some(Edit::Transposition),
            _ => None,
        };
    }
    let (longer, shorter) = if a.len() == b.len() + 1 {
        (a, b)
    } else if b.len() == a.len() + 1 {
        (b, a)
    } else {
        return None;
    };
    let i = (0..shorter.len()).find(|&i| longer[i] != shorter[i]).unwrap_or(shorter.len());
    if longer[i + 1..] != shorter[i..] {
        return None;
    }
    let extra = longer[i];
    if extra == '-' {
        return None;
    }
    let doubled = (i > 0 && longer[i - 1] == extra) || longer.get(i + 1) == Some(&extra);
    Some(if doubled { Edit::Duplication } else { Edit::Omission })
}

/// Whether a name this far from a popular one reads as a typo of it rather
/// than a word of its own: swaps, doubled letters and look-alikes at four
/// letters or more, a missing, extra or replaced letter at six or more
/// (`libm`/`libc`, `glow`/`glob`, `mime`/`time` are different crates).
fn is_typo(e: Edit, len: usize) -> bool {
    match e {
        Edit::Transposition | Edit::Duplication | Edit::Confusable => len >= MIN_LEN,
        Edit::Omission | Edit::Substitution => len >= 6,
    }
}

/// The popular scope a scoped name is one slip from, if any. Scopes are
/// owned by organizations and often legitimately a letter apart (@next,
/// @nuxt): only a swap, a double letter or a look-alike counts.
fn near_scope(pop: &Popular, scope: &str) -> Option<&'static str> {
    if scope.chars().count() < MIN_SCOPE_LEN {
        return None;
    }
    pop.scopes
        .iter()
        .copied()
        .filter(|c| matches!(edit(scope, c), Some(Edit::Transposition | Edit::Duplication | Edit::Confusable)))
        .min()
}

/// The popular name an unscoped name is one keystroke from, if any.
fn near_name(pop: &Popular, name: &str) -> Option<&'static str> {
    let c = canon(name);
    if pop.canon.contains(&c) || pop.folded.contains(&fold(name)) {
        return None;
    }
    let chars: Vec<char> = c.chars().collect();
    let len = chars.len();
    (len.saturating_sub(1)..=len + 1)
        .filter_map(|l| pop.by_len.get(&l))
        .flatten()
        .filter(|cand| edit_chars(&chars, &cand.canon).is_some_and(|e| is_typo(e, cand.canon.len())))
        .map(|cand| cand.name)
        .min()
}

/// The squats among these packages.
pub fn find(packages: &[Package]) -> Vec<Squat> {
    let mut out = Vec::new();
    let present: HashSet<(String, String)> =
        packages.iter().map(|p| (p.ecosystem.to_ascii_lowercase(), canon(&p.name))).collect();
    for p in packages {
        let eco = p.ecosystem.to_ascii_lowercase();
        let Some(pop) = POPULAR.get(&eco) else { continue };
        let name = p.name.to_ascii_lowercase();
        if pop.names.contains(name.as_str()) {
            continue;
        }
        let squat = match name.strip_prefix('@').and_then(|_| name.split_once('/')) {
            Some((scope, bare)) => {
                if pop.scopes.contains(scope) {
                    continue;
                }
                near_scope(pop, scope).map(|near| (format!("{near}/{bare}"), false))
            }
            None => {
                if name.chars().count() < MIN_LEN {
                    continue;
                }
                near_name(pop, &name).map(|near| (near.to_string(), present.contains(&(eco.clone(), canon(near)))))
            }
        };
        if let Some((near, both)) = squat {
            out.push(Squat { ecosystem: p.ecosystem.clone(), name: p.name.clone(), near, both });
        }
    }
    out.sort_by(|a, b| (&a.ecosystem, &a.name).cmp(&(&b.ecosystem, &b.name)));
    out.dedup_by(|a, b| a.ecosystem == b.ecosystem && a.name == b.name);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pkg(eco: &str, name: &str) -> Package {
        Package::new(eco, name, "1.0.0")
    }

    fn near(eco: &str, name: &str) -> Option<String> {
        find(&[pkg(eco, name)]).pop().map(|s| s.near)
    }

    #[test]
    fn edits() {
        assert_eq!(edit("lodahs", "lodash"), Some(Edit::Transposition));
        assert_eq!(edit("lodas", "lodash"), Some(Edit::Omission));
        assert_eq!(edit("lodashs", "lodash"), Some(Edit::Omission));
        assert_eq!(edit("lodaash", "lodash"), Some(Edit::Duplication));
        assert_eq!(edit("expres", "express"), Some(Edit::Duplication));
        assert_eq!(edit("lodesh", "lodash"), Some(Edit::Substitution));
        assert_eq!(edit("@babe1", "@babel"), Some(Edit::Confusable));
        assert_eq!(edit("lodash", "underscore"), None);
        assert_eq!(edit("preact", "react"), Some(Edit::Omission));
        assert_eq!(edit("xml-js", "xml2js"), None, "a separator for a letter is a different word");
        assert_eq!(edit("uuidv4", "uuidv7"), None, "a digit for a digit is a version");
        assert_eq!(edit("0penai", "openai"), Some(Edit::Confusable), "a digit for a letter can be a look-alike");
        assert_eq!(edit("nodefetch", "node-fetch"), None, "a dropped separator is the registry's business");
        assert_eq!(distance("lodash", "lodahs"), 1);
        assert!(!is_typo(Edit::Substitution, 4), "mime is not a typo of time");
        assert!(is_typo(Edit::Transposition, 4));
    }

    #[test]
    fn canonical_names() {
        assert_eq!(canon("Python_DateUtil"), "python-dateutil");
        assert_eq!(canon("socket.io"), "socket-io");
        assert_eq!(canon("foo--bar"), "foo-bar");
        assert_eq!(fold("ansi-colors"), "ansicolors");
    }

    #[test]
    fn squats_warn_and_a_typo_beside_the_real_one_is_both() {
        let s = find(&[pkg("npm", "lodahs"), pkg("npm", "react"), pkg("npm", "express")]);
        assert_eq!(s.len(), 1, "{s:?}");
        assert_eq!((s[0].name.as_str(), s[0].near.as_str(), s[0].both), ("lodahs", "lodash", false));
        let s = find(&[pkg("npm", "lodahs"), pkg("npm", "lodash")]);
        assert!(s[0].both);
        assert!(find(&[pkg("npm", "preact"), pkg("npm", "react")]).is_empty(), "both popular");
        assert!(find(&[pkg("npm", "colors"), pkg("npm", "color")]).is_empty(), "both popular");
        assert!(
            find(&[pkg("npm", "nodefetch"), pkg("npm", "ansicolors"), pkg("npm", "query-string")]).is_empty(),
            "npm refuses a name that differs from an existing one only by punctuation: a name that does is the older one"
        );
        assert!(find(&[pkg("npm", "ms"), pkg("npm", "qs")]).is_empty(), "short names are skipped");
        assert_eq!(near("npm", "@babe1/core").as_deref(), Some("@babel/core"));
        assert!(find(&[pkg("npm", "@babel/core"), pkg("npm", "@mycompany/react")]).is_empty());
        assert!(
            find(&[pkg("npm", "@next/env"), pkg("npm", "@clack/core")]).is_empty(),
            "a scope a letter apart is a scope"
        );
        assert_eq!(near("npm", "lodesh").as_deref(), Some("lodash"));
        assert!(
            find(&[
                pkg("crates.io", "libm"),
                pkg("crates.io", "libc"),
                pkg("crates.io", "mime"),
                pkg("crates.io", "time")
            ])
            .is_empty(),
            "short names a letter apart are words of their own"
        );
        assert!(find(&[pkg("npm", "ntapi")]).is_empty(), "five letters, one extra: a word of its own");
    }

    #[test]
    fn separators_are_the_same_package() {
        assert!(find(&[pkg("PyPI", "python_dateutil")]).is_empty(), "PEP 503: one package");
        assert!(find(&[pkg("PyPI", "Scikit-Learn")]).is_empty());
        assert_eq!(near("PyPI", "reqeusts").as_deref(), Some("requests"));
        assert!(
            near("PyPI", "sklearn").is_none(),
            "too far from scikit-learn; the squat is in the malicious index instead"
        );
        assert!(find(&[pkg("crates.io", "serde"), pkg("crates.io", "serde_json")]).is_empty());
        assert!(find(&[pkg("crates.io", "serde-json")]).is_empty(), "crates.io reads - and _ as one name");
        assert_eq!(near("crates.io", "serde_jsn").as_deref(), Some("serde_json"));
        assert_eq!(near("crates.io", "serde-jsn").as_deref(), Some("serde_json"), "the slip is the missing letter");
        assert!(find(&[pkg("Go", "github.com/x/y")]).is_empty(), "no list for the ecosystem");
    }

    /// The pairs a real scan of a developer machine flagged, every one two
    /// established packages, beside the squats the check is for. Four of
    /// that scan's pairs still warn, the typed name being below every
    /// ranking's cut: `scrypt`/`bcrypt`, `sqlite`/`sqlite3`,
    /// `tslint-config-airbnb`/`eslint-config-airbnb`, `valirator`/`validator`.
    #[test]
    fn established_packages_are_not_typos_of_each_other() {
        let pairs = [
            ("query-string", "querystring"),
            ("scrypt-js", "bcryptjs"),
            ("stylis", "stylus"),
            ("crypt", "bcrypt"),
            ("queue", "p-queue"),
            ("tslint", "eslint"),
            ("motion", "emotion"),
            ("rc-motion", "remotion"),
            ("xml-js", "xml2js"),
            ("colord", "colors"),
            ("ansicolors", "ansi-colors"),
            ("emoticon", "emotion"),
            ("sha-1", "sha1"),
            ("ansistyles", "ansi-styles"),
            ("scrypt.js", "bcryptjs"),
            ("buffers", "buffer"),
            ("mquery", "jquery"),
            ("tokenize-rt", "tokenizers"),
            ("uuidv4", "uuidv7"),
        ];
        let packages: Vec<Package> = pairs.iter().flat_map(|(a, b)| [pkg("npm", a), pkg("npm", b)]).collect();
        let flagged: Vec<(String, String)> = find(&packages).into_iter().map(|s| (s.name, s.near)).collect();
        assert!(flagged.is_empty(), "{flagged:?}");
        for (typed, meant) in [("lodahs", "lodash"), ("@babe1/core", "@babel/core"), ("lodesh", "lodash")] {
            assert_eq!(near("npm", typed).as_deref(), Some(meant));
        }
        let s = find(&[pkg("npm", "lodahs"), pkg("npm", "lodash")]);
        assert!(s[0].both, "the typo beside the name meant");
    }
}
